// Generated by scripts/build-landgrid.mjs from the Natural Earth land mask. Do not edit.
// 360×180 cells (1°), row 0 = 89.5°N, col 0 = 179.5°W. 128 = coast, >128 land.
export const LAND_W = 360;
export const LAND_H = 180;
export const LAND_B64 = '';

let grid: Uint8Array | null = null;
export function landGrid(): Uint8Array {
  if (grid) return grid;
  const bin = atob(LAND_B64);
  grid = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) grid[i] = bin.charCodeAt(i);
  return grid;
}

/** signed coast value at lat/lon in [-1, 1] (positive = land) */
export function landAt(lat: number, lon: number): number {
  const g = landGrid();
  const y = Math.max(0, Math.min(LAND_H - 1, Math.floor(90 - lat)));
  const x = ((Math.floor(lon + 180) % LAND_W) + LAND_W) % LAND_W;
  return (g[y * LAND_W + x]! - 128) / 127;
}
